import XCTest

final class UITests: XCTestCase {
    func testOpenBookClubNotifications() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()

        let bookClub = app.staticTexts["Book Club"].firstMatch
        XCTAssertTrue(bookClub.waitForExistence(timeout: 15), "Book Club not found")
        bookClub.press(forDuration: 1.2)

        var target: XCUIElement?
        if app.buttons["Notifications"].firstMatch.waitForExistence(timeout: 5) {
            target = app.buttons["Notifications"].firstMatch
        } else if app.menuItems["Notifications"].firstMatch.waitForExistence(timeout: 3) {
            target = app.menuItems["Notifications"].firstMatch
        } else if app.staticTexts["Notifications"].firstMatch.waitForExistence(timeout: 3) {
            target = app.staticTexts["Notifications"].firstMatch
        }
        if target == nil {
            try app.debugDescription.write(toFile: "/tmp/ui_hierarchy.txt", atomically: true, encoding: .utf8)
            XCTFail("Notifications item not found; hierarchy dumped")
            return
        }
        target!.tap()
        Thread.sleep(forTimeInterval: 2)
    }
}

