import XCTest

final class NavTests: XCTestCase {
    func testGotoSecurityPrivacy() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.launch()

        func dump(_ path: String) {
            try? app.debugDescription.write(toFile: path, atomically: true, encoding: .utf8)
        }

        let userMenu = app.buttons["User menu"]
        XCTAssertTrue(userMenu.waitForExistence(timeout: 20), "User menu not found")
        userMenu.tap()

        let userSettings = app.buttons["User settings"]
        XCTAssertTrue(userSettings.waitForExistence(timeout: 10), "User settings not found")
        userSettings.tap()

        var row = app.staticTexts["Security & Privacy"].firstMatch
        if !row.waitForExistence(timeout: 10) {
            row = app.staticTexts["Security"].firstMatch
        }
        if !row.waitForExistence(timeout: 5) {
            dump("/tmp/hier_nav_fail.txt")
            XCTFail("Security & Privacy row not found")
            return
        }
        row.tap()
        Thread.sleep(forTimeInterval: 3)
        dump("/tmp/hier_nav_done.txt")
    }
}
